#!/usr/bin/env bash
# Audit trail: prints, for every claim family, the exact log lines the numbers come from.
PTQ_EVAL="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; PY="${PTQ_PY:-$HOME/venv_et131_gpu/bin/python3}"; OUT="${PTQ_OUT:-$PTQ_EVAL/out}"; mkdir -p "$OUT"
M="$OUT"; cd "$M"
acc() { grep -E "^== |top1" "$1" 2>/dev/null | sed -E 's/.*fp32=([0-9.]+) (.*)=([0-9.]+)$/   fp32=\1 => \3/' | paste - - | awk -v f="$1" '{printf "  %-70s %s\n", substr($0,1,70), $NF}' ; }
wer() { grep -o "^== .*\|WER=[0-9.]*%.*hit_limit=[0-9]*" "$1" 2>/dev/null | paste - - | awk '{printf "  %-60s %s %s\n", substr($0,1,60), $(NF-2), $NF}'; }
low() { for f in "$@"; do printf "  %-34s %s | %s\n" "$f" "$(grep -E '\[EthosU85\+Vela\] partitions' lower_cost/$f.stdout 2>/dev/null | grep -o 'partitions=[0-9]* delegated=[0-9]* cpu=[0-9]*')" "$(grep -E 'Batch Inference time' lower_cost/$f.stdout 2>/dev/null | awk '{s+=$4} END {printf "%.1f ms (%d part)", s, NR}')"; done; }
echo "### A. accuracy, 50k ImageNet (label = exact rule set; per-run dirs: swin_ethosu/ptq_eval/imagenet50k/<model>__<tag>/)"; acc run_50k_deit.log; acc run_50k_swin.log; acc run_50k_pcsym.log
echo "### B. accuracy, FQ-ViT native same-venv 50k (fork test_quant.py)"; grep -E "^== |\* Prec@1" run_fqvit_native_50k.log run_fqvit_native_50k_nolis.log 2>/dev/null | sed -E 's/^([^:]*):== ([a-z_]+) \[(.*)\].*/\1 \2 [\3]/; s/ Prec@5.*//' | paste - - | awk '{printf "  %-60s %s\n", substr($0,1,60), $NF}'
echo "### C. accuracy, Whisper 200 utt (hyps: whisper_ethosu/ptq_eval/et131_*/ or mlek_setup/pcrw/*/)"; for f in run_whisper_deploy_pcs_newton run_whisper_small_newton run_whisper_base_pcs run_whisper_base_fc2_pc run_whisper_small_ln_bisect run_ln_variants2 run_overnight_dual_cas4k1; do echo "  [$f.log]"; wer $f.log; done
echo "### C2. Whisper full test-clean (2620 utt): fullset/"; grep -E "^== |2620/2620" run_fullset_whisper_cas4k0.log run_fullset_whisper_casada.log 2>/dev/null | cut -c1-140
echo "### D. annotation / per-tensor dtypes (fake-quant DAG dumps; regenerate: block_dag.py <model> <block> '<rules>')"; ls -1 deit_t_b0norm1_newton1_dag.txt swin_l2ds_leak_dag.txt swin_l2ds_transparent_dag.txt swin_l2b5_ptf_dag.txt deit_b5_ptf_dag.txt 2>/dev/null | sed 's/^/  /'; echo "  LN op census + rsqrt grids: $(ls -d $PTQ_EVAL/et131_ws_lnb_dump pcrw/w*_lndump 2>/dev/null | tr '\n' ' ')"
echo "### E. lowering (TOSA + Ethos-U85 Vela; lower_cost/<tag>.stdout has the rule set, partition counts, cpu_ops, tosa op/dtype census, Vela summary; lower_cost/<tag>/summary.json)"
low deit_t_a8w8_stock deit_t_a8w8_ln32 deit_t_a8w8_ln32_swap0 deit_t_pcsym8i32o8_pcrw2 deit_t_a16w8_stock deit_b_a8w8_ln32_res16 deit_b_pcsym8i32o8_pcrw deit_b_a16w8_stock swin_t_a8w8_stock swin_t_pcsym8i32o8_pcrw swin_t_stage3_ln32 swin_t_a16w8_stock whisper_a8w8_stock whisper_a16w8_stock whisper_a16w8_ln32 whisper_a16w8_ln32_newton1 whisper_deploy_v4_pcrw whisper_v4_o8 whisper_v4_o16 deit_t_res8i32o16 deit_t_res8i32o8_maskaware swin_t_pcsym_pcrw_maskaware whisper_dec_v4_embfp32 whisper_dec_v4_emb8 whisper_v4_dual_newton1 deit_t_ln32_dual
echo "### F. rewrite / pass validations"; echo "  pc_rewrite site exactness: pc_rewrite_site_check.py (rerun); accuracy with/without: run_pcrw_deit_t.log run_pcrw_more.log run_pcrw_b_diag.log run_whisper_base_pcrw.log"; acc run_pcrw_deit_t.log; acc run_pcrw_more.log; acc run_pcrw_b_diag.log; wer run_whisper_base_pcrw.log
echo "  memory-op pass: run_swin_mrg_i32o8.log (no-pass control 50.7) / run_swin_global_mem.log (carrier 79.3) / run_swin_transparent.log + run_swin_merge_o16.log (transparent 79.1 / 79.8)"
echo "### G. calibration-only diagnostics (no labels): run_ln_var_census2.log (per-token var range by size), run_levels_report.log (advisor), whisper_fc2_census3.log (sink census)"
